1	// Meeting-room booking server: JSON API + static page, data kept in one JSON file.
2	// Node.js built-ins only. Run: node server.mjs
3	import { createServer } from 'node:http';
4	import { readFileSync } from 'node:fs';
5	import { readFile, writeFile } from 'node:fs/promises';
6	import { resolve } from 'node:path';
7	
8	const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
9	const MAX_BODY_BYTES = 10000;
10	const MAX_PORT = 65535;
11	const DEFAULT_PORT = 3000;
12	const DEFAULT_DATA_FILE = 'bookings.json';
13	const JSON_TYPE = 'application/json; charset=utf-8';
14	const BOOKING_KEYS = Object.freeze(['date', 'end', 'id', 'room', 'start', 'title']);
15	const BOOKINGS_PREFIX = '/api/bookings/';
16	
17	const PAGE_FILES = Object.freeze({
18	  '/': { url: new URL('./public/index.html', import.meta.url), type: 'text/html; charset=utf-8' },
19	  '/app.js': { url: new URL('./public/app.js', import.meta.url), type: 'text/javascript; charset=utf-8' },
20	});
21	
22	const MSG = Object.freeze({
23	  notFound: 'not found',
24	  methodNotAllowed: 'method not allowed',
25	  bookingNotFound: 'booking not found',
26	  internal: 'internal error',
27	  contentType: 'content type must be application/json',
28	  tooLarge: 'body too large',
29	  notObject: 'body must be a JSON object',
30	  room: `room must be one of ${ROOMS.join(', ')}`,
31	  title: 'title must be 1 to 80 characters',
32	  date: 'date must be a valid YYYY-MM-DD date',
33	  start: 'start must be HH:MM',
34	  end: 'end must be HH:MM',
35	  order: 'end must be after start',
36	});
37	
38	// ---------- field validation (pure) ----------
39	
40	const DATE_RE = /^([0-9]{4})-([0-9]{2})-([0-9]{2})$/;
41	const TIME_RE = /^([0-9]{2}):([0-9]{2})$/;
42	
43	function isValidDate(value) {
44	  if (typeof value !== 'string') return false;
45	  const match = DATE_RE.exec(value);
46	  if (!match) return false;
47	  const [year, month, day] = match.slice(1).map(Number);
48	  if (year < 2000 || year > 2099 || month < 1 || month > 12) return false;
49	  const febDays = year % 4 === 0 ? 29 : 28;
50	  const daysInMonth = [31, febDays, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
51	  return day >= 1 && day <= daysInMonth;
52	}
53	
54	function isValidTime(value) {
55	  if (typeof value !== 'string') return false;
56	  const match = TIME_RE.exec(value);
57	  return match !== null && Number(match[1]) <= 23 && Number(match[2]) <= 59;
58	}
59	
60	function isValidTitle(title) {
61	  return typeof title === 'string' && title.length >= 1 && title.length <= 80;
62	}
63	
64	function isPlainObject(value) {
65	  return typeof value === 'object' && value !== null && !Array.isArray(value);
66	}
67	
68	function overlaps(a, b) {
69	  return a.room === b.room && a.date === b.date && a.start < b.end && b.start < a.end;
70	}
71	
72	// Rules 4-9. Returns { error } or { fields } with the trimmed title.
73	function validateFields(input) {
74	  const { room, title, date, start, end } = input;
75	  if (typeof room !== 'string' || !ROOMS.includes(room)) return { error: MSG.room };
76	  const trimmed = typeof title === 'string' ? title.trim() : null;
77	  if (!isValidTitle(trimmed)) return { error: MSG.title };
78	  if (!isValidDate(date)) return { error: MSG.date };
79	  if (!isValidTime(start)) return { error: MSG.start };
80	  if (!isValidTime(end)) return { error: MSG.end };
81	  if (end <= start) return { error: MSG.order };
82	  return { fields: { room, title: trimmed, date, start, end } };
83	}
84	
85	// Rule 10: the overlapping booking that starts earliest, or undefined.
86	function findConflict(bookings, candidate) {
87	  return bookings
88	    .filter((b) => overlaps(b, candidate))
89	    .reduce((first, b) => (first === undefined || b.start < first.start ? b : first), undefined);
90	}
91	
92	function compareBookings(a, b) {
93	  if (a.date !== b.date) return a.date < b.date ? -1 : 1;
94	  if (a.start !== b.start) return a.start < b.start ? -1 : 1;
95	  return ROOMS.indexOf(a.room) - ROOMS.indexOf(b.room);
96	}
97	
98	// ---------- startup ----------
99	
100	function fail(line) {
101	  process.stderr.write(`${line}\n`, () => process.exit(1));
102	}
103	
104	function parsePort(raw) {
105	  if (raw === undefined || raw === '') return DEFAULT_PORT;
106	  if (!/^[0-9]+$/.test(raw)) return null;
107	  const port = Number(raw);
108	  return port <= MAX_PORT ? port : null;
109	}
110	
111	function isStoredBooking(value) {
112	  if (!isPlainObject(value)) return false;
113	  const keys = Object.keys(value).sort();
114	  if (keys.length !== BOOKING_KEYS.length || keys.some((k, i) => k !== BOOKING_KEYS[i])) return false;
115	  if (!Number.isSafeInteger(value.id) || value.id < 1) return false;
116	  const check = validateFields(value);
117	  return check.fields !== undefined && check.fields.title === value.title;
118	}
119	
120	function isValidStore(data) {
121	  if (!isPlainObject(data)) return false;
122	  const keys = Object.keys(data).sort();
123	  if (keys.length !== 2 || keys[0] !== 'bookings' || keys[1] !== 'nextId') return false;
124	  const { nextId, bookings } = data;
125	  if (!Number.isSafeInteger(nextId) || nextId < 1 || !Array.isArray(bookings)) return false;
126	  if (!bookings.every((b) => isStoredBooking(b) && b.id < nextId)) return false;
127	  if (new Set(bookings.map((b) => b.id)).size !== bookings.length) return false;
128	  return bookings.every((b, i) => bookings.slice(i + 1).every((o) => !overlaps(b, o)));
129	}
130	
131	// Returns the store, or null when the file cannot be used.
132	function loadStore(filePath) {
133	  let text;
134	  try {
135	    text = readFileSync(filePath, 'utf8');
136	  } catch (err) {
137	    return err.code === 'ENOENT' ? { nextId: 1, bookings: [] } : null;
138	  }
139	  try {
140	    const data = JSON.parse(text);
141	    return isValidStore(data) ? { nextId: data.nextId, bookings: data.bookings } : null;
142	  } catch {
143	    return null;
144	  }
145	}
146	
147	// ---------- replies ----------
148	
149	function sendJson(res, status, payload) {
150	  const body = JSON.stringify(payload);
151	  res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': Buffer.byteLength(body) });
152	  res.end(body);
153	}
154	
155	function sendError(res, status, message) {
156	  sendJson(res, status, { error: message });
157	}
158	
159	function sendNoContent(res) {
160	  res.writeHead(204);
161	  res.end();
162	}
163	
164	// Reads the whole body; buffers at most MAX_BODY_BYTES + 1 bytes but always drains it all.
165	function readBody(req) {
166	  return new Promise((resolveBody, rejectBody) => {
167	    const chunks = [];
168	    let total = 0;
169	    let buffered = 0;
170	    req.on('data', (chunk) => {
171	      total += chunk.length;
172	      if (buffered <= MAX_BODY_BYTES) {
173	        chunks.push(chunk);
174	        buffered += chunk.length;
175	      }
176	    });
177	    req.on('end', () => resolveBody({ total, buffer: Buffer.concat(chunks) }));
178	    req.on('error', rejectBody);
179	  });
180	}
181	
182	function isJsonContentType(header) {
183	  if (typeof header !== 'string') return false;
184	  const media = header.split(';')[0].replace(/^[ \t]+|[ \t]+$/g, '');
185	  return media.replace(/[A-Z]/g, (c) => c.toLowerCase()) === 'application/json';
186	}
187	
188	// Rules 1-3. Returns { status, error } or { value } with the parsed object.
189	function parseJsonBody(req, body) {
190	  if (!isJsonContentType(req.headers['content-type'])) return { status: 415, error: MSG.contentType };
191	  if (body.total > MAX_BODY_BYTES) return { status: 413, error: MSG.tooLarge };
192	  let value;
193	  try {
194	    value = JSON.parse(body.buffer.toString('utf8'));
195	  } catch {
196	    return { status: 400, error: MSG.notObject };
197	  }
198	  return isPlainObject(value) ? { value } : { status: 400, error: MSG.notObject };
199	}
200	
201	// ---------- app ----------
202	
203	function createApp(initialStore, filePath) {
204	  let store = initialStore;
205	  let queue = Promise.resolve();
206	
207	  // Runs mutations one at a time so concurrent requests behave as if sequential.
208	  function serialize(task) {
209	    const run = queue.then(task);
210	    queue = run.catch(() => undefined);
211	    return run;
212	  }
213	
214	  // Saves next to disk, then makes it the in-memory truth. Throws on save failure.
215	  async function commit(next) {
216	    await writeFile(filePath, JSON.stringify(next));
217	    store = next;
218	  }
219	
220	  function listBookings(res, query) {
221	    const params = new URLSearchParams(query);
222	    const date = params.has('date') ? params.get('date') : null;
223	    if (date !== null && !isValidDate(date)) return sendError(res, 400, MSG.date);
224	    const selected = date === null ? store.bookings : store.bookings.filter((b) => b.date === date);
225	    return sendJson(res, 200, { bookings: [...selected].sort(compareBookings) });
226	  }
227	
228	  async function createBooking(req, res, body) {
229	    const parsed = parseJsonBody(req, body);
230	    if (parsed.error) return sendError(res, parsed.status, parsed.error);
231	    const checked = validateFields(parsed.value);
232	    if (checked.error) return sendError(res, 400, checked.error);
233	    return serialize(async () => {
234	      const conflict = findConflict(store.bookings, checked.fields);
235	      if (conflict) {
236	        return sendError(res, 409, `room is already booked from ${conflict.start} to ${conflict.end}`);
237	      }
238	      const booking = { id: store.nextId, ...checked.fields };
239	      await commit({ nextId: store.nextId + 1, bookings: [...store.bookings, booking] });
240	      return sendJson(res, 201, booking);
241	    });
242	  }
243	
244	  async function deleteBooking(res, idText) {
245	    return serialize(async () => {
246	      const valid = /^[1-9][0-9]*$/.test(idText);
247	      const target = valid ? store.bookings.find((b) => String(b.id) === idText) : undefined;
248	      if (!target) return sendError(res, 404, MSG.bookingNotFound);
249	      await commit({ nextId: store.nextId, bookings: store.bookings.filter((b) => b !== target) });
250	      return sendNoContent(res);
251	    });
252	  }
253	
254	  async function servePage(res, page) {
255	    const content = await readFile(page.url);
256	    res.writeHead(200, { 'Content-Type': page.type, 'Content-Length': content.length });
257	    res.end(content);
258	  }
259	
260	  async function route(req, res, body) {
261	    const target = req.url;
262	    const cut = target.indexOf('?');
263	    const path = cut === -1 ? target : target.slice(0, cut);
264	    const query = cut === -1 ? '' : target.slice(cut + 1);
265	    const method = req.method;
266	
267	    if (path === '/api/rooms') {
268	      return method === 'GET' ? sendJson(res, 200, { rooms: [...ROOMS] }) : sendError(res, 405, MSG.methodNotAllowed);
269	    }
270	    if (path === '/api/bookings') {
271	      if (method === 'GET') return listBookings(res, query);
272	      if (method === 'POST') return createBooking(req, res, body);
273	      return sendError(res, 405, MSG.methodNotAllowed);
274	    }
275	    if (path.startsWith(BOOKINGS_PREFIX)) {
276	      const idText = path.slice(BOOKINGS_PREFIX.length);
277	      if (idText === '' || idText.includes('/')) return sendError(res, 404, MSG.notFound);
278	      return method === 'DELETE' ? deleteBooking(res, idText) : sendError(res, 405, MSG.methodNotAllowed);
279	    }
280	    if (Object.hasOwn(PAGE_FILES, path)) {
281	      return method === 'GET' ? servePage(res, PAGE_FILES[path]) : sendError(res, 405, MSG.methodNotAllowed);
282	    }
283	    return sendError(res, 404, MSG.notFound);
284	  }
285	
286	  function replyInternalError(res) {
287	    if (res.headersSent) {
288	      res.destroy();
289	      return;
290	    }
291	    sendError(res, 500, MSG.internal);
292	  }
293	
294	  return async function handle(req, res) {
295	    try {
296	      const body = await readBody(req);
297	      await route(req, res, body);
298	    } catch (err) {
299	      // Any unexpected failure (a failed save included) becomes a 500; the server keeps running.
300	      // The cause goes to stderr (never stdout); the client only sees `internal error`.
301	      process.stderr.write(`request failed: ${err?.code ?? err?.name ?? 'error'}\n`);
302	      replyInternalError(res);
303	    }
304	  };
305	}
306	
307	function main() {
308	  const port = parsePort(process.env.PORT);
309	  if (port === null) return fail('invalid PORT: must be digits 0-9 with a value up to 65535');
310	
311	  const dataName = process.env.DATA_FILE || DEFAULT_DATA_FILE;
312	  const filePath = resolve(process.cwd(), dataName);
313	  const store = loadStore(filePath);
314	  if (store === null) return fail(`cannot read data file ${dataName}`);
315	
316	  const server = createServer(createApp(store, filePath));
317	  server.on('error', (err) => fail(`cannot listen on port ${port}: ${err.code ?? 'error'}`));
318	  server.listen(port, '127.0.0.1', () => {
319	    process.stdout.write(`listening on http://127.0.0.1:${server.address().port}\n`);
320	  });
321	  return undefined;
322	}
323	
324	main();
325

1	// Shared helpers for the server tests: spawn `node server.mjs`, temp dirs, raw HTTP.
2	// No tests live here; node --test may load this file and find none.
3	import { spawn } from 'node:child_process';
4	import { mkdtemp, rm } from 'node:fs/promises';
5	import { tmpdir } from 'node:os';
6	import { join } from 'node:path';
7	import { fileURLToPath } from 'node:url';
8	import http from 'node:http';
9	import net from 'node:net';
10	
11	export const SERVER_PATH = fileURLToPath(new URL('../../server.mjs', import.meta.url));
12	const TIMEOUT_MS = 5000;
13	const LISTEN_RE = /^listening on http:\/\/127\.0\.0\.1:([0-9]+)\n$/;
14	
15	export const makeTempDir = () => mkdtemp(join(tmpdir(), 'rooms-test-'));
16	export const removeDir = (dir) => rm(dir, { recursive: true, force: true });
17	
18	// Builds the child env: inherits process.env without PORT/DATA_FILE, then applies `env`.
19	// A key whose value is undefined is left unset.
20	function childEnv(env) {
21	  const base = { ...process.env };
22	  delete base.PORT;
23	  delete base.DATA_FILE;
24	  const merged = { ...base, ...env };
25	  return Object.fromEntries(Object.entries(merged).filter(([, v]) => v !== undefined));
26	}
27	
28	function spawnServer({ cwd, env }) {
29	  return spawn(process.execPath, [SERVER_PATH], { cwd, env: childEnv(env), stdio: ['ignore', 'pipe', 'pipe'] });
30	}
31	
32	// Runs the server expecting it to exit (startup failure). Resolves { code, stdout, stderr }.
33	export function runToExit({ cwd, env = {} }) {
34	  return new Promise((resolve, reject) => {
35	    const child = spawnServer({ cwd, env });
36	    let stdout = '';
37	    let stderr = '';
38	    child.stdout.setEncoding('utf8').on('data', (d) => { stdout += d; });
39	    child.stderr.setEncoding('utf8').on('data', (d) => { stderr += d; });
40	    const timer = setTimeout(() => {
41	      child.kill('SIGKILL');
42	      reject(new Error(`server did not exit; stdout=${JSON.stringify(stdout)}`));
43	    }, TIMEOUT_MS);
44	    child.on('error', reject);
45	    child.on('close', (code) => {
46	      clearTimeout(timer);
47	      resolve({ code, stdout, stderr });
48	    });
49	  });
50	}
51	
52	// Starts the server (default PORT=0) and waits for the listening line.
53	// Resolves { port, child, stdout(), stderr(), stop() }; stop() kills and awaits exit.
54	export function startServer({ cwd, env = {} }) {
55	  return new Promise((resolve, reject) => {
56	    const child = spawnServer({ cwd, env: { PORT: '0', ...env } });
57	    let stdout = '';
58	    let stderr = '';
59	    let exited = false;
60	    const exitPromise = new Promise((r) => child.on('close', (code) => { exited = true; r(code); }));
61	    const stop = async () => {
62	      if (!exited) child.kill('SIGKILL');
63	      return exitPromise;
64	    };
65	    const timer = setTimeout(() => {
66	      stop();
67	      reject(new Error(`server did not start; stderr=${JSON.stringify(stderr)}`));
68	    }, TIMEOUT_MS);
69	    child.stderr.setEncoding('utf8').on('data', (d) => { stderr += d; });
70	    child.stdout.setEncoding('utf8').on('data', (d) => {
71	      stdout += d;
72	      const match = LISTEN_RE.exec(stdout);
73	      if (match) {
74	        clearTimeout(timer);
75	        resolve({ port: Number(match[1]), child, stdout: () => stdout, stderr: () => stderr, stop, exited: () => exited });
76	      }
77	    });
78	    child.on('close', (code) => {
79	      clearTimeout(timer);
80	      reject(new Error(`server exited with ${code} before listening; stderr=${JSON.stringify(stderr)}`));
81	    });
82	  });
83	}
84	
85	// One HTTP request via http.request (path sent as given, no normalisation).
86	// Resolves { status, headers, body: Buffer, text, json() }.
87	export function request(port, { method = 'GET', path = '/', headers = {}, body } = {}) {
88	  return new Promise((resolve, reject) => {
89	    const req = http.request({ host: '127.0.0.1', port, method, path, headers, agent: false }, (res) => {
90	      const chunks = [];
91	      res.on('data', (c) => chunks.push(c));
92	      res.on('end', () => {
93	        const buf = Buffer.concat(chunks);
94	        const text = buf.toString('utf8');
95	        resolve({ status: res.statusCode, headers: res.headers, body: buf, text, json: () => JSON.parse(text) });
96	      });
97	      res.on('error', reject);
98	    });
99	    req.on('error', reject);
100	    req.end(body);
101	  });
102	}
103	
104	export const getJson = (port, path) => request(port, { path });
105	
106	export function postBooking(port, booking, headers = { 'Content-Type': 'application/json' }) {
107	  const body = typeof booking === 'string' || Buffer.isBuffer(booking) ? booking : JSON.stringify(booking);
108	  return request(port, { method: 'POST', path: '/api/bookings', headers, body });
109	}
110	
111	// Writes raw bytes on a TCP socket and resolves with everything received until the server closes it.
112	// Send `Connection: close` so the server ends the socket after replying.
113	export function rawRequest(port, data) {
114	  return new Promise((resolve, reject) => {
115	    const socket = net.connect(port, '127.0.0.1');
116	    const chunks = [];
117	    const timer = setTimeout(() => { socket.destroy(); reject(new Error('raw request timed out')); }, TIMEOUT_MS);
118	    socket.on('data', (c) => chunks.push(c));
119	    socket.on('error', (err) => { clearTimeout(timer); reject(err); });
120	    socket.on('close', () => { clearTimeout(timer); resolve(Buffer.concat(chunks).toString('latin1')); });
121	    socket.end(data);
122	  });
123	}
124	
125	// Parses a raw HTTP/1.1 response (single, non-chunked) into { status, headers, body }.
126	export function parseRaw(raw) {
127	  const split = raw.indexOf('\r\n\r\n');
128	  const head = raw.slice(0, split).split('\r\n');
129	  const status = Number(head[0].split(' ')[1]);
130	  const headers = Object.fromEntries(head.slice(1).map((line) => {
131	    const i = line.indexOf(':');
132	    return [line.slice(0, i).trim().toLowerCase(), line.slice(i + 1).trim()];
133	  }));
134	  return { status, headers, body: Buffer.from(raw.slice(split + 4), 'latin1').toString('utf8') };
135	}
136	
137	export const JSON_TYPE = 'application/json; charset=utf-8';
138

