const BAD_FILES = [
  { label: 'directory', given: 'adir', check: 'adir', content: null },
  { label: 'ENOTDIR', given: 'afile/data.json', check: 'afile', content: 'plain' },
  { label: 'empty file', given: 'b.json', check: 'b.json', content: '' },
