test('pipelined 2 MB 415 POST then GET on one socket: both replies arrive', async (t) => {
  const dir = await tmp(t);
  const server = await boot(t, { cwd: dir, env: { DATA_FILE: 'd.json' } });
  const big = 'x'.repeat(2_000_000);
  const first = 'POST /api/bookings HTTP/1.1\r\nHost: x\r\nContent-Type: text/plain\r\n'
    + `Content-Length: ${big.length}\r\n\r\n${big}`;
  const second = 'GET /api/rooms HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n';
  const raw = await rawRequest(server.port, first + second);
  const parts = raw.split('HTTP/1.1 ');
  assert.equal(parts.length, 3);
  assert.ok(parts[1].startsWith('415 '));
  assert.ok(parts[2].startsWith('200 '));
  assert.deepEqual(JSON.parse(parts[1].split('\r\n\r\n')[1]), { error: 'content type must be application/json' });
  assert.deepEqual(parseRaw(`HTTP/1.1 ${parts[2]}`).body && JSON.parse(parseRaw(`HTTP/1.1 ${parts[2]}`).body),
    { rooms: ['Aurora', 'Borealis', 'Cosmos'] });
});
